SELECT DATE_TRUNC('MONTH', launch_date) AS launch_month, CASE WHEN category IN ('Books', 'Electronics') THEN 'core' ELSE 'other' END AS category_group, ROUND(AVG(price), 2) AS avg_price FROM products WHERE price > 1130 AND (category != 'Books' OR cost > 630) GROUP BY DATE_TRUNC('MONTH', launch_date), CASE WHEN category IN ('Books', 'Electronics') THEN 'core' ELSE 'other' END ORDER BY avg_price, launch_month, category_group LIMIT 5;
